import{_ as o,o as r,c as a,a2 as d}from"./chunks/framework.Bqa2y7hU.js";const p=JSON.parse('{"title":"群管使用指南","description":"群管插件的完整功能说明：内容检测与处罚、入群验证与审批、黑白名单、授权系统、问答、统计、签到、定时、主人与副主。","frontmatter":{"title":"群管使用指南","description":"群管插件的完整功能说明：内容检测与处罚、入群验证与审批、黑白名单、授权系统、问答、统计、签到、定时、主人与副主。"},"headers":[],"relativePath":"console/group-admin.md","filePath":"console/group-admin.md","lastUpdated":1789292506000}'),e={name:"console/group-admin.md"};function s(n,t,l,i,c,g){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="群管使用指南" tabindex="-1">群管使用指南 <a class="header-anchor" href="#群管使用指南" aria-label="Permalink to &quot;群管使用指南&quot;">​</a></h1><p>群管是随框架提供的最完整的一个插件：从内容拦截、成员处置到入群管理、问答、统计、签到、定时播报都能覆盖。装到机器人上之后，大部分功能都在<strong>插件面板</strong>里配，常用操作也可以在群里用指令完成。</p><div class="tip custom-block"><p class="custom-block-title">面板在哪</p><p>控制台 → 我的机器人 → 选中机器人 → 「插件」Tab → 群里管理 → 进入插件面板。 面板是<strong>按机器人</strong>隔离的：同一插件装在两台机器人上，配置互不影响。</p></div><h2 id="权限模型-先搞清这个" tabindex="-1">权限模型（先搞清这个） <a class="header-anchor" href="#权限模型-先搞清这个" aria-label="Permalink to &quot;权限模型（先搞清这个）&quot;">​</a></h2><p>群管的所有管理指令都按下面的顺序判权限：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主人 &gt; 副主 &gt; 群主 / 群管理员 &gt; 普通成员</span></span></code></pre></div><table tabindex="0"><thead><tr><th>角色</th><th>说明</th></tr></thead><tbody><tr><td><strong>主人</strong></td><td>在插件面板里配置的账号列表。<strong>留空时，该群的群主自动视为主人</strong>，所以开箱即用</td></tr><tr><td><strong>副主</strong></td><td>主人之外再授权若干人，可执行管理指令（只有主人能增删副主）</td></tr><tr><td>群主 / 群管理员</td><td>由平台上报的群内角色，自动放行</td></tr><tr><td>普通成员</td><td>只能使用面向成员的指令（签到、我的统计、问答等）</td></tr></tbody></table><h2 id="一、内容检测与处罚" tabindex="-1">一、内容检测与处罚 <a class="header-anchor" href="#一、内容检测与处罚" aria-label="Permalink to &quot;一、内容检测与处罚&quot;">​</a></h2><p><strong>检测项</strong>（每一项独立开关 + 独立处置）：</p><table tabindex="0"><thead><tr><th>检测</th><th>说明</th></tr></thead><tbody><tr><td>违禁词</td><td>分群词库 + 全局词库两级</td></tr><tr><td>链接 / 卡片 / 转发消息</td><td>分别拦截</td></tr><tr><td>手机号</td><td>自动识别手机号格式</td></tr><tr><td>QQ 号</td><td>自动识别纯数字账号</td></tr><tr><td>刷屏</td><td>时间窗口 + 条数阈值判定</td></tr><tr><td><strong>全撤模式</strong></td><td>非白名单、非管理员的消息<strong>一律撤回</strong>（最严格的一档）</td></tr></tbody></table><p><strong>处置档位</strong>：<code>警告</code> / <code>撤回</code> / <code>禁言</code> / <code>踢出</code>（可带拉黑），每项检测可单独指定。</p><p><strong>处罚升级</strong>：可以设置「警告 N 次后自动禁言」，也可以设置<strong>阶梯禁言</strong>（第 1/2/3 次违规分别禁言不同时长，超出次数沿用最后一档）。所有违规都会记进<strong>违规记录</strong>，可按人查看与清除。</p><p>命中处罚时，如果开了「回执提醒」，群里会播报处理结果。</p><h2 id="二、入群验证与审批" tabindex="-1">二、入群验证与审批 <a class="header-anchor" href="#二、入群验证与审批" aria-label="Permalink to &quot;二、入群验证与审批&quot;">​</a></h2><p><strong>入群验证</strong>：新人进群先答题（算术题，QQ 官方平台会带按钮选项），验证期内发言会被撤回；答错按阶梯延长冷却。可配置：</p><ul><li>验证有效期（默认 5 分钟，答错后自动翻倍，有上限）</li><li>验证期间是否禁言</li><li><strong>免验证名单</strong>：名单内的人进群直接放行</li></ul><p><strong>入群审批</strong>：有人申请入群时，把申请播报到群里（QQ 官方平台带「同意 / 拒绝」按钮），也可以：</p><ul><li>用指令审批：<code>同意 &lt;编号&gt;</code> / <code>拒绝 &lt;编号&gt; [原因]</code></li><li>设置审批策略：手动 / 自动通过 / 自动拒绝 / 自动拉黑</li><li><strong>关键词审批</strong>：申请留言命中关键词时自动通过</li></ul><h2 id="三、成员处置" tabindex="-1">三、成员处置 <a class="header-anchor" href="#三、成员处置" aria-label="Permalink to &quot;三、成员处置&quot;">​</a></h2><ul><li><strong>禁言</strong>：<code>禁言 @成员 [分钟]</code>、<code>禁言 &lt;用户ID&gt; [分钟]</code>，也可以<strong>引用某人的消息</strong>后直接发 <code>禁言 10</code></li><li><strong>永久禁言</strong>：受平台单次禁言上限约束，本插件用「平台上限 + 到期自动续期」实现</li><li><strong>踢出</strong>：<code>踢出 @成员 [拉黑]</code></li><li>另有<strong>针对撤回名单</strong>（名单内成员的消息全部自动撤回）、<strong>撤回最近 N 条</strong>、<strong>禁言记录</strong>与<strong>单人禁言状态查询</strong></li></ul><h2 id="四、黑白名单" tabindex="-1">四、黑白名单 <a class="header-anchor" href="#四、黑白名单" aria-label="Permalink to &quot;四、黑白名单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名单</th><th>作用</th></tr></thead><tbody><tr><td><strong>黑名单</strong></td><td>该成员的消息被撤回，其指令被忽略</td></tr><tr><td><strong>白名单</strong></td><td>该成员<strong>免于本插件的全部处罚与拦截</strong>（信任名单）</td></tr></tbody></table><p>各自都有「本群」与「全局」两份。同时出现在两个名单里时，<strong>白名单优先</strong>。</p><h2 id="五、授权系统-把群管当服务卖时用" tabindex="-1">五、授权系统（把群管当服务卖时用） <a class="header-anchor" href="#五、授权系统-把群管当服务卖时用" aria-label="Permalink to &quot;五、授权系统（把群管当服务卖时用）&quot;">​</a></h2><p>默认<strong>不启用</strong>，不影响任何群。启用「授权模式」后，<strong>未授权的群不会执行拦截、也不响应群管指令</strong>（主人和副主仍然可用，方便现场处理）。</p><ul><li>给当前群或指定群授权：<code>30 天</code> / <code>90 天</code> / <code>永久</code>，可以带备注</li><li>随时查询某群剩余天数、清除单个或全部授权</li><li><strong>到期提示</strong>：快到期时（默认剩余 3 天内）在群里提醒一次，每天最多一次</li></ul><h2 id="六、问答-统计-签到-定时" tabindex="-1">六、问答 / 统计 / 签到 / 定时 <a class="header-anchor" href="#六、问答-统计-签到-定时" aria-label="Permalink to &quot;六、问答 / 统计 / 签到 / 定时&quot;">​</a></h2><table tabindex="0"><thead><tr><th>系统</th><th>能做什么</th></tr></thead><tbody><tr><td><strong>问答</strong></td><td>精准问答（整词相等）与模糊问答（包含即命中），各有「本群」与「全局」两套；<code>精准问你好答你好呀</code> 这样增删查</td></tr><tr><td><strong>统计</strong></td><td>发言日榜 / 周榜 / 月榜，我的发言与我的统计，进群 / 退群统计；可开关「榜单记录」与「榜单查询权限」</td></tr><tr><td><strong>签到</strong></td><td><code>签到</code> 得随机积分（默认 5~15），连续签到有额外奖励；有日榜与总榜；货币名称、奖励区间、连续签到目标都可配</td></tr><tr><td><strong>定时</strong></td><td><code>添加定时 21:30#晚上好</code>，到点自动往群里播报；支持开关与删除</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">统计与榜单默认是关的</p><p>「榜单记录」默认关闭（避免一装就产生持续增长的存储）。需要时在面板或群里发「开启榜单记录」。</p></div><div class="warning custom-block"><p class="custom-block-title">定时播报依赖平台授权</p><p>定时消息属于<strong>主动消息</strong>，在没授权的群会发送失败（属平台限制，不是插件故障）。失败只记审计，不会刷屏。</p></div><h2 id="七、入群-退群提示" tabindex="-1">七、入群 / 退群提示 <a class="header-anchor" href="#七、入群-退群提示" aria-label="Permalink to &quot;七、入群 / 退群提示&quot;">​</a></h2><p>可以分别设置<strong>入群提示</strong>与<strong>退群提示</strong>的文案并单独开关，群里有人进出时自动播报。</p><div class="tip custom-block"><p class="custom-block-title">和「入群欢迎」插件的关系</p><p>群管自带的提示更完整（支持退群提示）；独立的「入群欢迎」插件保留给只需要欢迎语的场景。两者可以同时装，不冲突。</p></div><h2 id="八、常用指令速查" tabindex="-1">八、常用指令速查 <a class="header-anchor" href="#八、常用指令速查" aria-label="Permalink to &quot;八、常用指令速查&quot;">​</a></h2><p>在群里 @ 机器人发「<strong>群管菜单</strong>」，会按分组列出全部指令（开关设置 / 词库管理 / 处罚管理 / 禁言管理 / 入群管理 / 刷屏设置 / 问答系统 / 统计系统 / 签到系统 / 定时系统 / 黑白名单 / 授权系统 / 主人系统 / 运维指令）。</p><p>发分组名（例如「处罚管理」）可以只看该组的指令，不用记完整的指令表。</p><p><strong>所有面向用户可见的文案都可以改</strong>：面板「回复模板」里有 100 多条模板，支持 Markdown 与纯文本两版，改完立即生效。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/RuaBot.Doc/console/plugins">插件市场与安装</a>：怎么把插件装到机器人上</li><li><a href="/RuaBot.Doc/console/builtin-plugins">内置插件一览</a>：其它内置插件</li><li><a href="/RuaBot.Doc/reference/capabilities">平台能力码</a>：群管依赖的平台权限</li></ul>',39)])])}const u=o(e,[["render",s]]);export{p as __pageData,u as default};
